using namespace g9;struct FakePolicy:IAgentPolicy{LoopConfig lc{4,4,65536};AgentRequest before_prompt(const AgentRequest&r)override{return r;}std::vector<ChatMessage>build_messages(const AgentRequest&r)override{return{{"system","code"},{"user",r.prompt}};}std::string render_prompt(const std::vector<ChatMessage>&,const GenerationConfig&,const JsonValue&,const JsonValue&h)override{return serialize_json(h);}GenerationConfig generation_settings(const AgentRequest&)override{return{};}AgentResponse after_response(const AgentResponse&r)override{return r;}const LoopConfig&loop()const noexcept override{return lc;}};struct FakeRuntime:IGenerationRuntime{int n=0;GenerationResult generate(std::string_view,const GenerationConfig&,std::stop_token)override{++n;if(n==1)return{"<function name=\"read_file\"><param name=\"path\">x.cpp</param></function>",4,5,false,false};return{"done",6,2,true,false};}};int main(){Guardrails g(GuardrailProfile::balanced);ToolRegistry tools(g);JsonValue schema(JsonValue::object{{"type","object"},{"properties",JsonValue::object{{"path",JsonValue::object{{"type","string"}}}}},{"required",JsonValue::array{JsonValue("path")}},{"additionalProperties",false}});tools.add({"read_file","read",schema,RiskClass::read},[](const JsonValue&){ActionDescriptor a;a.tool="read_file";a.risk=RiskClass::read;return a;},[](const JsonValue&){ToolResult r;r.disposition=ToolDisposition::completed;r.ok=true;r.payload=JsonValue::object{{"text","hello"}};r.display_summary="read";return r;});FakePolicy p;FakeRuntime runtime;Session s;AgentLoop loop(p,runtime,tools,g,{},{});auto out=loop.run(s,AgentRequest{"fix"});CHECK_EQ(out.output,"done");CHECK_EQ(out.tool_steps,1u);CHECK_EQ(out.usage.prompt_tokens,10);CHECK_EQ(out.usage.completion_tokens,7);return test_support::finish();}
